contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We take params: open (bool) to decide calling OpenToThePublic, betAmount to send to wager,
    // and whaleAddr and wagerLimit are irrelevant here because c is already deployed by the checker.
    function run(bool doOpen, uint256 betAmount) public payable {
        require(address(this).balance >= betAmount || betAmount == 0, "balance");
        // Ensure contract is open if requested: onlyOwner modifier prevents this contract from opening it
        // So we only call OpenToThePublic if it doesn't revert. We must try/catch since it may revert.
        bool opened = false;
        try c.OpenToThePublic() {
            opened = true;
        } catch {
            opened = false;
        }
        // If the caller asks not to open, or opening reverted, respect doOpen parameter by trying only when requested.
        // Now attempt to place a wager only if we think contract is open (either we opened it or user didn't request open)
        // We'll attempt wager and record whether it reverted.
        bool wagerReverted;
        try c.wager{value: betAmount}() {
            wagerReverted = false;
        } catch {
            wagerReverted = true;
        }
        // Observations through public surface
        // hasPlayerWagered should reflect whether wager succeeded
        bool recorded = c.hasPlayerWagered(address(this));
        uint256 pot = c.winnersPot();
        uint256 cBal = address(c).balance;
        // General rule:
        // If wager did not revert then hasPlayerWagered(this) must be true.
        // Additionally, winnersPot is always equal to address(c).balance/2 (the contract's view) and therefore pot*2 <= cBal*2 (avoid multiplication overflow) — simpler: pot*2 == cBal - (cBal % 2)
        // But asserts must be general and use only observed values. We'll state:
        // If wager succeeded then recorded is true, and pot*2 <= cBal*2 (i.e. pot <= cBal).
        // This captures that winnersPot is at most full balance and combined with payout logic it should be half; requiring pot <= cBal is non-trivial.
        assert((!wagerReverted && recorded) && (pot <= cBal));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // params: open the contract, send exactly betLimit as wagerAmount, and provide a gasless play trigger
    function run(bool tryOpen, uint256 wagerAmount) public payable {
        require(address(this).balance >= wagerAmount, "insufficient test balance");
        // attempt to open to public (may revert if not owner)
        bool opened;
        try c.OpenToThePublic() {
            opened = true;
        } catch {
            opened = false;
        }
        // read current bet limit
        uint256 limit = c.currentBetLimit();
        // only attempt a valid wager amount equal to current betLimit; otherwise we will try and observe revert
        bool wagerReverted;
        // place wager only if we provide exactly limit as required by contract; send value wagerAmount to allow exploration
        if (wagerAmount == limit) {
            try c.wager{value: wagerAmount}() {
                wagerReverted = false;
            } catch {
                wagerReverted = true;
            }
        } else {
            // don't call; mark as reverted (wasn't done)
            wagerReverted = true;
        }
        // capture balances and recorded wager flag before play
        uint256 balBefore = address(c).balance;
        bool hadWagerBefore = c.hasPlayerWagered(address(this));
        // attempt to call play and record whether it reverted
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }
        uint256 balAfter = address(c).balance;
        bool hasWagerAfter = c.hasPlayerWagered(address(this));
        // General invariant to hold for ALL inputs:
        // If play succeeded (didn't revert), then the caller should no longer have an active wager (hasPlayerWagered == false),
        // and the contract balance after is <= balance before (play either pays out to winner from contract or transfers to whale, so it should not increase).
        assert((!playReverted) ? (hasWagerAfter == false && balAfter <= balBefore) : true);
    }
    receive() external payable {}
}

