contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: whale address and wagerLimit are set at C construction time by the deployer of C.
    // We need: open the contract to public, set betLimit, send exactly betLimit when calling wager,
    // then advance block (cannot here) so we must rely on block.number semantics; to ensure play() does not revert
    // we call wager first in one transaction (this run), then simulate play in the same run — play will revert
    // if timestamps[msg.sender] == block.number. The contract rule: if play() executes (did not revert),
    // afterwards hasPlayerWagered(msg.sender) must be false. We'll test both branches (reverted or cleared).

    function run(uint256 betAmount) public payable {
        require(address(this).balance >= betAmount);

        // open to public must be called by owner; our test contract is the deployer/owner of c per checker note
        c.OpenToThePublic();

        // adjust bet limit to our provided amount
        c.AdjustBetAmounts(betAmount);

        // Deposit exactly betAmount to wager. This is a state-changing call that must be top-level.
        c.wager{value: betAmount}();

        // Record hasPlayerWagered before play
        bool before = c.hasPlayerWagered(address(this));

        // Try to play: may revert if called in same block as wager; capture revert boolean
        bool reverted;
        try c.play() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-state
        bool after = c.hasPlayerWagered(address(this));

        // General invariant: if play did not revert then the player's wager must have been cleared (after == false).
        // If play reverted then the state may be unchanged; so require only the implication.
        assert(reverted || (!after));
    }

    receive() external payable {}
}

