        // Make the contract open to public and set the bet limit to betAmount. As deployer of C,
        // this test contract is the owner and can call these.
        c.OpenToThePublic();
        c.AdjustBetAmounts(betAmount);

        // Place a wager by sending exactly betAmount. This is a top-level state-changing call.
        c.wager{value: betAmount}();

        // Capture whether play() reverts.
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }

        // Observe whether the contract still considers this address a player.
        bool stillWagered = c.hasPlayerWagered(address(this));

        // Assert the invariant: if play did not revert then the wager must have been cleared.
        assert(playReverted || (!stillWagered));
    }

