    function run(bool open, uint256 amount) public payable {
        require(address(this).balance >= amount);
        // If requested, open the contract to public by calling OpenToThePublic from owner (this contract is owner)
        if(open){
            c.OpenToThePublic();
        }
        // read observable before-values
        uint256 beforeBal = address(c).balance;
        bool reverted;
        // Call wager with value=amount; capture revert
        try c.wager{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterBal = address(c).balance;
        // Determine current betLimit and hasPlayerWagered for this contract (msg.sender == this test)
        uint256 betLimit = c.currentBetLimit();
        bool hasWager = c.hasPlayerWagered(address(this));
        // General rule:
        // - If call reverted, then either contract was not openToPublic or amount != betLimit (so no balance change and hasPlayerWagered false)
        // - If call succeeded, then amount == betLimit and hasPlayerWagered true and balance increased by amount
        assert(
            // success case: not reverted implies amount matched betLimit, hasPlayerWagered true, and balance increased by amount
            (!reverted && amount == betLimit && hasWager && afterBal == beforeBal + amount)
            // or revert case: reverted implies either not opened or amount != betLimit, and no balance change and hasPlayerWagered false
            || (reverted && afterBal == beforeBal && hasWager == false)
