    // wager and a successful play call (non-revert), the player has no active wager and either winnersPot decreased
    // accordingly or totalDonated increased. Because totalDonated is not public, we observe effects via hasPlayerWagered and address(c).balance

    // run takes: whale address (for constructor of C it used when C was deployed externally), amount to set as betLimit,
    // and amountSent to wager. The test will require amountSent == betLimit and payable for sending Ether to c.wager().
    function run(uint256 newBetLimit, uint256 amountSent) public payable {
        require(msg.sender == address(this)); // ensure only this contract invokes run externally in this single-transaction model
        // open contract to public and set betLimit via owner-only functions — note: InvMutTest is the deployer of C per harness description,
        // so this contract is the owner and may call these.
        c.OpenToThePublic();
        c.AdjustBetAmounts(newBetLimit);

        // Ensure we have the funds to send wager
        require(address(this).balance >= amountSent);

        // Precondition for exercising play: must send exactly the bet limit to wager
