        uint256 balBefore = address(c).balance;
        bool hadWagerBefore = c.hasPlayerWagered(address(this));

        // Attempt to call play and capture revert status
        bool reverted;
        try c.play() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After attempt, read observable state
        uint256 balAfter = address(c).balance;
        bool hasWagerAfter = c.hasPlayerWagered(address(this));

        // General rule asserted: If the play call did NOT revert and there was a wager recorded before,
        // then after the call the player must no longer be recorded as having a wager, and either the contract's balance
        // decreased by at least (amountSent/2) (a loseWager transfer to whale) or decreased by at most balBefore/2 (a payout to player)
        // We express this as: not reverted && hadWagerBefore implies (!hasWagerAfter) && (balAfter <= balBefore && balAfter + (amountSent/2) <= balBefore + (balBefore/2))
        // Simplify to: not reverted && hadWagerBefore implies !hasWagerAfter && balAfter <= balBefore

