    constructor(C _c) { c = _c; }

    // The test deployer is the owner of C. We must avoid calling functions that revert in C's constructor context.
    // This run sets bet limit, opens to public, wagers exactly the current bet limit, then calls play and
    // asserts that if play did not revert then hasPlayerWagered is false for this contract.
    function run(uint256 newBetLimit, uint256 wagerAmount) public payable {
        // Ensure this contract has enough ETH to place the wager
        require(address(this).balance >= wagerAmount);

        // Only the owner (this contract) can adjust and open — this contract deployed C so it is the owner.
        c.AdjustBetAmounts(newBetLimit);
        c.OpenToThePublic();

        // Require the provided wagerAmount equals the current bet limit so wager() should accept it
        require(wagerAmount == c.currentBetLimit());

        // place the wager
        c.wager{value: wagerAmount}();

        // ensure that before play the contract is recorded as having wagered
        bool hadWager = c.hasPlayerWagered(address(this));
        require(hadWager);

        // try to play and record whether it reverted
        bool reverted;
        try c.play() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After attempting play, assert: if play did not revert then the player no longer has an active wager
        assert(reverted || !c.hasPlayerWagered(address(this)));
    }

    receive() external payable { }
}

