contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run attempts to open the contract, set bet limit, and then call wager with amount 'amt'.
    // It asserts that when wager succeeds, hasPlayerWagered(msg.sender) is true and address(c).balance increased by amt;
    // when wager reverts, hasPlayerWagered(msg.sender) remains false and balance unchanged.
    function run(uint256 setBetLimit, uint256 amt, address whale, bool open) public payable {
        // Preconditions for doing payable calls: ensure this contract has enough balance to forward amt
        require(address(this).balance >= amt);

        // Deploy-time constructor of C has already run (checker deploys fresh C). We can call owner-only AdjustBetAmounts and OpenToThePublic only if this contract is owner.
        // The deployed C's owner is the address that deployed it (the checker). We cannot become owner, so we must operate within public API.
        // But OpenToThePublic and AdjustBetAmounts are onlyOwner; therefore we cannot call them. Instead we observe currentBetLimit and currentDifficulty and proceed.
        // To satisfy the template requirement to set up state as needed, we will attempt to call wager and observe whether it reverts or not.

        // Record before-state
        uint256 beforeBalance = address(c).balance;
        bool beforeHas = c.hasPlayerWagered(address(this));

        // Attempt to call wager with exactly amt (which must equal c.currentBetLimit() for success) and only allowed if openToPublic true.
        bool reverted;
        // Ensure we send exactly amt as Ether
        try c.wager{value: amt}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = address(c).balance;
        bool afterHas = c.hasPlayerWagered(address(this));

        // General rule:
        // - If the call did not revert then it must have been because msg.value == betLimit and contract was open; observable consequences: hasPlayerWagered becomes true and contract balance increases by amt.
        // - If the call reverted then hasPlayerWagered remains equal to beforeHas and balance unchanged.
        assert(
            (!reverted && afterHas && afterBalance == beforeBalance + amt) || (reverted && afterHas == beforeHas && afterBalance == beforeBalance)
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call donate with a chosen amount; assert that either the call reverted and c's balance stayed the same,
    // or it succeeded and c's balance decreased by exactly amount and winnersPot decreased by amount/2.
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        uint256 beforeBal = address(c).balance;
        uint256 beforeWinners = c.winnersPot();

        bool reverted;
        try c.donate{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBal = address(c).balance;
        uint256 afterWinners = c.winnersPot();

        // General rule:
        // - If donate reverted: contract balance and winnersPot unchanged.
        // - If donate succeeded: the contract balance decreased by exactly amount, and winnersPot decreased by amount/2.
        assert((reverted && afterBal == beforeBal && afterWinners == beforeWinners) ||
               (!reverted && beforeBal >= amount && afterBal + amount == beforeBal &&
                // winnersPot is defined as address(this).balance / 2; afterBal = beforeBal - amount so winnersPot should drop by amount/2 (floor division semantics)
                afterWinners * 2 + amount == beforeWinners * 2)
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Inputs: amount to wager (must equal betLimit to succeed), and a dummy difficulty to set.
    // We require enough balance to send the wager amount. The test will:
    // 1) open the contract to public by calling OpenToThePublic() as owner (this contract is the deployer/owner of c).
    // 2) ensure betLimit equals amount by calling AdjustBetAmounts(amount).
    // 3) call wager{value: amount}()
    // 4) advance no blocks (cannot), but we observe timestamps: play requires the stored block < current block,
    //    so we call play() and accept either revert (if condition fails) or success. If play succeeds, it must clear the player's wager.
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        // Setup: make contract open and set bet limit to amount. This contract is the owner per problem statement.
        c.OpenToThePublic();
        c.AdjustBetAmounts(amount);

        // Read pre-state: whether we currently have a wager (should be false initially)
        bool beforeHas = c.hasPlayerWagered(address(this));

        // Place a wager paying exactly amount
        c.wager{value: amount}();

        // After wagering, hasPlayerWagered must be true
        bool afterWagerHas = c.hasPlayerWagered(address(this));

        // Record values before calling play
        bool reverted;
        try c.play() {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool afterPlayHas = c.hasPlayerWagered(address(this));

        // General invariant to assert for all inputs/executions:
        // - The wager call established a wager (afterWagerHas == true).
        // - If play reverted then the post-play hasPlayerWagered may remain true or false (we don't constrain it),
        //   but if play succeeded (not reverted) then the contract must have cleared the caller's wager (afterPlayHas == false).
        // Also ensure that before placing a wager it was not already marked (a modest precondition about initial effect).
        assert(beforeHas == false && afterWagerHas == true && (reverted || afterPlayHas == false));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Inputs: amount to set as bet limit and to send as the wager value.
    // Precondition: this test contract must have enough Ether to pay the wager amount.
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        // Make the contract open to public and set the bet limit to the chosen amount.
        // This contract is the deployer/owner of c so onlyOwner modifiers pass.
        c.OpenToThePublic();
        c.AdjustBetAmounts(amount);

        // Record balance and hasPlayerWagered before wagering
        uint256 beforeBal = address(c).balance;
        bool beforeHas = c.hasPlayerWagered(address(this));

        // Attempt to wager by sending exactly `amount` wei.
        // We capture whether it reverted.
        bool reverted;
        try c.wager{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBal = address(c).balance;
        bool afterHas = c.hasPlayerWagered(address(this));

        // General rule: if wager succeeded (did not revert) then
        // 1) hasPlayerWagered(this) must be true, and
        // 2) contract balance increased by exactly `amount`.
        // If wager reverted then no guarantees (we only assert the implication).
        assert(reverted || (afterHas == true && afterBal == beforeBal + amount));
    }

    receive() external payable { }
}
